def _as_component_field(values: Iterable[float], label: str) -> ThroatField:
    primary = np.asarray(tuple(float(value) for value in values), dtype=float)
    return ThroatField(values=np.column_stack((primary, primary * 0.5)), label=label)

def active_coefficients(self) -> np.ndarray:
    if self.conductance is None:
        raise ValueError("No conductance field has been assigned")
    values = np.asarray(self.conductance, dtype=float)
    if values.ndim == 1:
        return values
    return values.mean(axis=1)

